changeSet.sql:
DO $$
DECLARE
    is_numeric boolean;
BEGIN
    SELECT data_type IN ('smallint', 'integer', 'bigint') INTO is_numeric
    FROM information_schema.columns
    WHERE table_schema = current_schema() AND table_name = 'city' AND column_name = 'level';

    IF is_numeric THEN
        UPDATE city SET level = 0 WHERE lower(replace(trim(name), 'Ł', 'ł')) IN ('final', 'finał');
        UPDATE city SET level = 1 WHERE level IS NULL;
    ELSE
        UPDATE city SET level = 'FINAL' WHERE lower(replace(trim(name), 'Ł', 'ł')) IN ('final', 'finał');
        UPDATE city SET level = 'REGIONAL' WHERE level IS NULL;
    END IF;
END $$;
